window.api.updates.getState()
      .then((info) => {
        if (!info) return
        if (['available', 'downloading', 'ready', 'error'].includes(info.phase)) {
          setUpdateMeta(info)
        }
        if (info.phase === 'downloading') {
          setUpdateStatus('available')
          setUpdateMessage(info.progress.bytesPerSecond > 0 ? `Downloading at ${formatBytes(/** @type {import('../types/desktop-api.js').DesktopUpdateProgressReadView} */ (info.progress).bytesPerSecond)}/s` : 'Downloading update…')
          setDownloadProgress(info.progress || null)
        } else if (info.phase === 'ready') {
          setUpdateReady(true)
          setUpdateStatus('available')
          setUpdateMessage('Download complete. Restart to install.')
        } else if (info.phase === 'error') {
          setUpdateStatus('error')
          setUpdateMessage(info.error || 'Update failed.')
        }
      })
      .catch

window.api.email.getConfig()
      .then((result) => {
        // Email IPC returns an unvalidated config value; retain its existing display defaults.
        const config = /** @type {Partial<SettingsEmailConfigExpectedView>|null} */ (result)
        if (!active || !config) return
        const provider = inferEmailProvider(config.host)
        const preset = EMAIL_PROVIDER_PRESETS[provider] || EMAIL_PROVIDER_PRESETS.custom
        const initialConfig = {
          provider,
          host: config.host || preset.host,
          port: Number(config.port) || preset.port,
          user: config.user || '',
          pass: config.pass || '',
          from: config.from || '',
          reply_to: config.reply_to || '',
          to: config.to || '',
          allow_insecure_tls: config.allow_insecure_tls === true,
          auto_send_quotations: config.auto_send_quotations === true,
          auto_send_booking_invoice: config.auto_send_booking_invoice === true,
          auto_send_booking_confirmation: config.auto_send_booking_confirmation === true,
          auto_send_booking_cancellation: config.auto_send_booking_cancellation === true
        }
        setEmailConfig(initialConfig)
        if (!savedEmailSnapshotRef.current) {
          savedEmailSnapshotRef.current = JSON.parse(JSON.stringify(initialConfig))
        }
      })
      .catch

window.api.trial.getStatus(lodgeId, { forceFresh: forceFresh === true }).then((status) => {
        // Trial IPC returns an unvalidated dynamic value; this is its expected display view.
        const statusView = /** @type {SettingsLicenseStatusExpectedView} */ (status)
        setLicenseStatus(statusView)
        return statusView
      }).catch

window.api.import.getBatches().then((data) => {
      // Main returns persisted import-batch rows; this expected view does not validate cached JSON.
      const rows = /** @type {ImportBatchExpectedView[]} */ (/** @type {unknown} */ (data))
      setBatches(Array.isArray(rows) ? rows : [])
      setLoading(false)
    }).catch

window.api.import.getTypes.()
      .then((types) => {
        const typeRows = /** @type {ImportTypeOption[]} */ (/** @type {unknown} */ (types))
        const allTypes = Array.isArray(typeRows) && typeRows.length ? typeRows : [{ key: 'bookings', label: 'Bookings', executable: true }]
        const filtered = restaurantMode
          ? allTypes.filter((t) => RESTAURANT_TYPES.has(t.key) || COMMON_TYPES.has(t.key))
          : allTypes.filter((t) => LODGE_ONLY_TYPES.has(t.key) || COMMON_TYPES.has(t.key))
        setImportTypes(filtered.length ? filtered : allTypes.slice(0, 1))
        if (filtered.length && !filtered.some((t) => t.key === importType)) {
          setImportType(filtered[0].key)
        }
      })
      .catch

window.api.pos.getStations.()
      .then((rows) => {
        const enabled = (Array.isArray(rows) ? rows : []).filter((row) => row.enabled !== false)
        const builtIns = [{ id: 'all', name: 'All stations' }, { id: 'kitchen', name: 'Kitchen' }, { id: 'bar', name: 'Bar' }]
        const merged = new Map(builtIns.map(row => [row.id, row]))
        enabled.forEach(row => merged.set(row.id, { id: row.id, name: row.name || row.id }))
        setStations([...merged.values()])
      })
      .catch

window.api.outlets.getAll.().then((rows) => {
      if (!active) return
      const all = Array.isArray(rows) ? rows : []
      const shared = all.filter((row) => row.cash_model === 'shared_drawer')
      setAllOutlets(all)
      setDrawerOutlets(shared)
      setDrawerOutletId((current) => current && shared.some((row) => row.id === current) ? current : shared[0].id || '')
      setOutletsLoaded(true)
    }).catch

